-- Paket ABT "abt-jawab-replik-31okt" (31 Okt 2026): naskah utuh jawab-menjawab (jawaban/replik/duplik/rekonvensi/kesimpulan) di BAS dan duduk perkara. Hanya derry_briantono.
-- PRASYARAT "A|B|C|D|E": A = 12020-12049 berisi lain (0) | B = variabel baru persis (0/16) | C = variabel lama persis dasar (6/0) | D = variabel lama sudah isi baru (0/6) | E = fungsi isian_rtf_blok/butir/par/keterangan ada (4)
SELECT CONCAT_WS('|',
 (SELECT COUNT(*) FROM abt_variabel v WHERE v.no_var BETWEEN 12020 AND 12049 AND NOT EXISTS (SELECT 1 FROM (SELECT 12020 AS n, '2c8ef08df0bab32558450c7767beec52' AS h UNION ALL SELECT 12021 AS n, '1d04a512b06c935475e389b12ed3d8f3' AS h UNION ALL SELECT 12022 AS n, 'ef19e73ddd1b53691fd51ab5ad9525ff' AS h UNION ALL SELECT 12023 AS n, '69508c107ecd3163c5d169d38c2b22dc' AS h UNION ALL SELECT 12024 AS n, '9d08c7c25b0399bd446c5dc8bf1a3782' AS h UNION ALL SELECT 12025 AS n, 'c9153663e6928807cda8355485a93053' AS h UNION ALL SELECT 12026 AS n, '4efdd1d89a238a07ed595dfa5435f3a9' AS h UNION ALL SELECT 12027 AS n, 'd2324920e74aefa843c2ab39cd39c325' AS h UNION ALL SELECT 12028 AS n, 'caaf01f13dbbac0f9b800438b5c04b7b' AS h UNION ALL SELECT 12030 AS n, '52881586589c9887833da802098e6d86' AS h UNION ALL SELECT 12031 AS n, '69ac26427b4c4e126c00fa75c168346c' AS h UNION ALL SELECT 12032 AS n, '6e90600b0baf248cfad02c48d0c78c4d' AS h UNION ALL SELECT 12033 AS n, 'e039a9bef5b86326a705ddee6212b255' AS h UNION ALL SELECT 12034 AS n, 'aeee9bb321cf600c4af92b8d78bafc4c' AS h UNION ALL SELECT 12035 AS n, '9d9acb2a4ce7016e133b9a44384fcba2' AS h UNION ALL SELECT 12036 AS n, '55e6b869ece1b6acebdbb1bad158296a' AS h) p WHERE p.n = v.no_var AND p.h = MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), IFNULL(v.referensi, ''), IFNULL(v.multi_sidang, ''), v.locked, IFNULL(v.modifier, ''))))),
 (SELECT COUNT(*) FROM abt_variabel v JOIN (SELECT 12020 AS n, '2c8ef08df0bab32558450c7767beec52' AS h UNION ALL SELECT 12021 AS n, '1d04a512b06c935475e389b12ed3d8f3' AS h UNION ALL SELECT 12022 AS n, 'ef19e73ddd1b53691fd51ab5ad9525ff' AS h UNION ALL SELECT 12023 AS n, '69508c107ecd3163c5d169d38c2b22dc' AS h UNION ALL SELECT 12024 AS n, '9d08c7c25b0399bd446c5dc8bf1a3782' AS h UNION ALL SELECT 12025 AS n, 'c9153663e6928807cda8355485a93053' AS h UNION ALL SELECT 12026 AS n, '4efdd1d89a238a07ed595dfa5435f3a9' AS h UNION ALL SELECT 12027 AS n, 'd2324920e74aefa843c2ab39cd39c325' AS h UNION ALL SELECT 12028 AS n, 'caaf01f13dbbac0f9b800438b5c04b7b' AS h UNION ALL SELECT 12030 AS n, '52881586589c9887833da802098e6d86' AS h UNION ALL SELECT 12031 AS n, '69ac26427b4c4e126c00fa75c168346c' AS h UNION ALL SELECT 12032 AS n, '6e90600b0baf248cfad02c48d0c78c4d' AS h UNION ALL SELECT 12033 AS n, 'e039a9bef5b86326a705ddee6212b255' AS h UNION ALL SELECT 12034 AS n, 'aeee9bb321cf600c4af92b8d78bafc4c' AS h UNION ALL SELECT 12035 AS n, '9d9acb2a4ce7016e133b9a44384fcba2' AS h UNION ALL SELECT 12036 AS n, '55e6b869ece1b6acebdbb1bad158296a' AS h) p ON p.n = v.no_var AND p.h = MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), IFNULL(v.referensi, ''), IFNULL(v.multi_sidang, ''), v.locked, IFNULL(v.modifier, '')))),
 (SELECT COUNT(*) FROM abt_variabel WHERE (no_var = 206 AND MD5(CONCAT_WS('|', nama, IFNULL(sql_query, ''))) = '8c8add18aeb481ae5c7440bcec781eab') OR (no_var = 9252 AND MD5(CONCAT_WS('|', nama, IFNULL(sql_query, ''))) = 'a6d42734a8754d176dd7f34d007e7577') OR (no_var = 9253 AND MD5(CONCAT_WS('|', nama, IFNULL(sql_query, ''))) = '0c1a6f487f11b10d9e6ac8252169316f') OR (no_var = 9254 AND MD5(CONCAT_WS('|', nama, IFNULL(sql_query, ''))) = '3cec9ad2922b061643b2173c950aee19') OR (no_var = 9257 AND MD5(CONCAT_WS('|', nama, IFNULL(sql_query, ''))) = 'ba5a58018abc4daaf4e6974455037628') OR (no_var = 9258 AND MD5(CONCAT_WS('|', nama, IFNULL(sql_query, ''))) = 'f3c0c96f00949553dad96aaa8074537b')),
 (SELECT COUNT(*) FROM abt_variabel WHERE (no_var = 206 AND MD5(CONCAT_WS('|', nama, IFNULL(sql_query, ''))) = '1c4f6cd2e95be3ac8eb26b704349a2b9') OR (no_var = 9252 AND MD5(CONCAT_WS('|', nama, IFNULL(sql_query, ''))) = '88c9c56aa43088a5f4080267fa91f9d2') OR (no_var = 9253 AND MD5(CONCAT_WS('|', nama, IFNULL(sql_query, ''))) = '7363ccd1cab9b48211d8b4d231d22cd0') OR (no_var = 9254 AND MD5(CONCAT_WS('|', nama, IFNULL(sql_query, ''))) = 'bfb7063cf25a2c49f82d5029674c90a2') OR (no_var = 9257 AND MD5(CONCAT_WS('|', nama, IFNULL(sql_query, ''))) = '9a991a2e51cd5030de588b718950d447') OR (no_var = 9258 AND MD5(CONCAT_WS('|', nama, IFNULL(sql_query, ''))) = '6598518ed515df572a7141cc4ec4b69e')),
 (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema = DATABASE() AND routine_name IN ('isian_rtf_blok', 'isian_rtf_butir', 'isian_rtf_par', 'isian_rtf_keterangan'))) AS p;
